software Notes {
  metadata { displayName "Notes"; namespace "example.notes"; }
  target { language java 21; framework spring_boot; persistence mybatis_plus; database mysql; build maven; interface rest; }
  sources { }
  imports { }
  declarations {
    entity User persistent {
      identity id: Id generated auto;
      field name: Name where length(1, 64) unique;
      field passwordHash: Secret;
    }

    entity AccessToken persistent {
      identity id: Token generated uuid;
      field owner: Ref<User>;
      field expiresAt: Moment;
      credential subject owner expires expiresAt;
    }

    entity Note persistent {
      identity id: Id generated auto;
      field author: Ref<User>;
      field text: Text where length(1, 255);
    }

    input RegisterInput {
      field name: Name where length(1, 64);
      field password: Secret;
    }

    input GetUserInput {
      field id: Id;
    }

    input LoginInput {
      field name: Name where length(1, 64);
      field password: Secret;
    }

    input LogoutInput {
      field token: Token;
    }

    input PostNoteInput {
      field text: Text where notBlank;
    }

    view UserView from User {
      field id: Id;
      field name: Name;
    }

    view TokenView from AccessToken {
      field id: Token;
      field expiresAt: Moment;
    }

    view NoteView from Note {
      field id: Id;
      field text: Text;
    }

    error BadLogin http 401;
    error BadToken http 401;
    error UserNotFound http 404;

    capability Register {
      input RegisterInput;
      output UserView;
      requires atomic;
      expose command at "/api/register";
      workflow {
        create User as account {
          name: input.name;
          passwordHash: input.password;
        }
        persist account;
        return account;
      }
    }

    capability GetUser {
      input GetUserInput;
      output UserView;
      fails UserNotFound;
      requires readonly;
      expose query at "/api/get-user";
      workflow {
        load User by input.id as account else UserNotFound;
        return account;
      }
    }

    capability Login {
      input LoginInput;
      output TokenView;
      fails BadLogin;
      requires atomic;
      expose command at "/api/login";
      workflow {
        load User by name: input.name as account else BadLogin;
        validate account.passwordHash matches input.password else BadLogin;
        create AccessToken as made {
          owner: account;
          expiresAt: now() + 15 minutes;
        }
        persist made;
        return made;
      }
    }

    capability Logout {
      input LogoutInput;
      output TokenView;
      fails BadToken;
      requires atomic;
      expose command at "/api/logout";
      workflow {
        load AccessToken by input.token as found else BadToken;
        delete found;
        return found;
      }
    }

    capability PostNote {
      actor Ref<User>;
      input PostNoteInput;
      output NoteView;
      requires authenticated;
      requires atomic;
      expose command at "/api/post-note";
      workflow {
        create Note as made {
          author: actor;
          text: input.text;
        }
        persist made;
        return made;
      }
    }
  }
}
